//! Rust port of the platform delivery protocol core.
//!
//! Contracts that MUST match `packages/cas-core/src/*` byte for byte:
//!   - `chunker`   FastCDC cut points (same GEAR seed / masks / bounds)
//!   - `manifest`  JSON shape, structural validation, path safety
//!   - `trust`     Ed25519 manifest signature verification, keyId derivation
//!
//! `tests/parity.rs` rereads `tests/fixtures/` — generated by the Node
//! reference (`npm run vectors`) — and fails the build on any divergence.
//! Do not change constants without regenerating fixtures AND bumping the
//! protocol schema.

pub mod chunker;
pub mod manifest;
pub mod trust;

pub mod client_runtime;
pub mod store;

pub use manifest::{assert_safe_path, Manifest, PLATFORMS, SCHEMA};
pub use trust::{key_id_of_raw, TrustStore};
